1|// Placeholder track selection. Pure: no env, no fetch, no audio.
2|import { EMOTIONS } from "./types";
3|import type { EmotionId, Vector8 } from "./types";
4|import { buildFeatures } from "./cluster";
5|
6|export interface Track {
7|  id: string;
8|  src: string;
9|  label: string;
10|  vector: Vector8;
11|  intensity: number;
12|  tempo: number;
13|  durationSec: number;
14|  loop: boolean;
15|}
16|
17|export interface MusicManifest {
18|  version: number;
19|  tracks: Track[];
20|}
21|
22|export interface SceneEmotion {
23|  vector: Vector8;
24|  intensity: number;
25|  tempo: number;
26|}
27|
28|const SUPPORTED_VERSION = 1;
29|
30|function isRecord(value: unknown): value is Record<string, unknown> {
31|  return typeof value === "object" && value !== null && !Array.isArray(value);
32|}
33|
34|function isVector8(value: unknown): value is Vector8 {
35|  if (!isRecord(value)) return false;
36|  return EMOTIONS.every((id: EmotionId) => typeof value[id] === "number");
37|}
38|
39|function isUnit(value: unknown): value is number {
40|  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1;
41|}
42|
43|function isSrc(value: unknown): value is string {
44|  return (
45|    typeof value === "string" &&
46|    (value.startsWith("/music/") || value.startsWith("https://"))
47|  );
48|}
49|
50|// Fail loudly on a bad drop-in manifest so broken files never play quiet.
51|export function parseManifest(json: unknown): MusicManifest {
52|  if (!isRecord(json)) throw new Error("manifest must be an object");
53|  if (json.version !== SUPPORTED_VERSION) throw new Error(`unsupported manifest version: ${String(json.version)}`);
54|  if (!Array.isArray(json.tracks)) throw new Error("manifest tracks must be an array");
55|  const tracks = json.tracks.map((entry, i) => {
56|    if (!isRecord(entry)) throw new Error(`track ${i} must be an object`);
57|    const { id, src, label, vector, intensity, tempo, durationSec, loop } = entry;
58|    if (typeof id !== "string" || id === "") throw new Error(`track ${i} needs a string id`);
59|    if (!isSrc(src)) throw new Error(`track ${id} src must be a /music/ path or https URL`);
60|    if (typeof label !== "string" || label === "") throw new Error(`track ${id} needs a label`);
61|    if (!isVector8(vector)) throw new Error(`track ${id} vector must cover the 8 emotion ids`);
62|    if (!isUnit(intensity)) throw new Error(`track ${id} intensity must be 0..1`);
63|    if (!isUnit(tempo)) throw new Error(`track ${id} tempo must be 0..1`);
64|    if (typeof durationSec !== "number" || !Number.isFinite(durationSec) || durationSec <= 0) {
65|      throw new Error(`track ${id} durationSec must be a positive number`);
66|    }
67|    if (typeof loop !== "boolean") throw new Error(`track ${id} loop must be a boolean`);
68|    return { id, src, label, vector, intensity, tempo, durationSec, loop };
69|  });
70|  return { version: SUPPORTED_VERSION, tracks };
71|}
72|
73|function cosine(a: number[], b: number[]): number {
74|  let dot = 0;
75|  let na = 0;
76|  let nb = 0;
77|  for (let i = 0; i < a.length; i++) {
78|    const x = a[i] ?? 0;
79|    const y = b[i] ?? 0;
80|    dot += x * y;
81|    na += x * x;
82|    nb += y * y;
83|  }
84|  if (na === 0 || nb === 0) return 0;
85|  return dot / (Math.sqrt(na) * Math.sqrt(nb));
86|}
87|
88|function ranked(scene: SceneEmotion | null, manifest: MusicManifest, currentTrackId: string | null): Track[] {
89|  if (scene === null) {
90|    // Failed scene with no vector: hold the current track first for stability.
91|    const current = manifest.tracks.find((t) => t.id === currentTrackId);
92|    const rest = manifest.tracks.filter((t) => t.id !== currentTrackId);
93|    return current ? [current, ...rest] : [...rest];
94|  }
95|  const target = buildFeatures(scene);
96|  return [...manifest.tracks].sort((a, b) => {
97|    const diff = cosine(buildFeatures(b), target) - cosine(buildFeatures(a), target);
98|    return diff !== 0 ? diff : manifest.tracks.indexOf(a) - manifest.tracks.indexOf(b);
99|  });
100|}
101|
102|// Nearest track by cosine similarity over vector plus weighted intensity
103|// and tempo. Hysteresis keeps the current track unless the best beats it
104|// by margin (default 0.05), which stops flicker between nearby scenes.
105|export function selectTrack(
106|  scene: SceneEmotion | null,
107|  manifest: MusicManifest,
108|  currentTrackId?: string | null,
109|  opts?: { margin?: number; exclude?: string[] },
110|): Track | null {
111|  if (manifest.tracks.length === 0) return null;
112|  const current = manifest.tracks.find((t) => t.id === (currentTrackId ?? null)) ?? null;
113|  if (scene === null) return current;
114|  const margin = opts?.margin ?? 0.05;
115|  const excluded = new Set(opts?.exclude ?? []);
116|  const candidates = ranked(scene, manifest, currentTrackId ?? null).filter((t) => !excluded.has(t.id));
117|  const best = candidates[0] ?? null;
118|  if (best === null) return null;
119|  if (current !== null && !excluded.has(current.id) && best.id !== current.id) {
120|    const target = buildFeatures(scene);
121|    if (cosine(buildFeatures(best), target) - cosine(buildFeatures(current), target) < margin) {
122|      return current;
123|    }
124|  }
125|  return best;
126|}
127|
128|// Next best track after the current one, wrapping around, so repeated
129|// presses cycle through every track. One track returns itself.
130|export function nextAlternative(
131|  scene: SceneEmotion | null,
132|  manifest: MusicManifest,
133|  currentTrackId: string | null,
134|): Track | null {
135|  if (manifest.tracks.length === 0) return null;
136|  if (manifest.tracks.length === 1) return manifest.tracks[0] ?? null;
137|  const order = ranked(scene, manifest, currentTrackId);
138|  const at = order.findIndex((t) => t.id === currentTrackId);
139|  return order[(at + 1) % order.length] ?? null;
140|}

