1|"use client";
2|
3|import { useEffect, useRef, useState } from "react";
4|import type { Track } from "@/core/music";
5|
6|// Placeholder player: two audio elements fade against each other on track
7|// change. Loop stays on. Nothing plays before the user presses play.
8|export function Player({
9|  track,
10|  sceneTitle,
11|  onSkip,
12|}: {
13|  track: Track | null;
14|  sceneTitle: string | null;
15|  onSkip: (() => void) | null;
16|}) {
17|  const firstRef = useRef<HTMLAudioElement | null>(null);
18|  const secondRef = useRef<HTMLAudioElement | null>(null);
19|  const liveRef = useRef(0);
20|  const [started, setStarted] = useState(false);
21|  const [playing, setPlaying] = useState(false);
22|  const [volume, setVolume] = useState(0.8);
23|  const playingRef = useRef(false);
24|  playingRef.current = playing;
25|
26|  const faded = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
27|
28|  useEffect(() => {
29|    for (const el of [firstRef.current, secondRef.current]) {
30|      if (el) el.volume = volume;
31|    }
32|  }, [volume]);
33|
34|  useEffect(() => {
35|    if (!started || !track) return;
36|    const els = [firstRef.current, secondRef.current];
37|    const live = els[liveRef.current];
38|    const standby = els[1 - liveRef.current];
39|    if (!live || !standby) return;
40|    if (live.src.endsWith(track.src) && !live.paused) return;
41|    standby.src = track.src;
42|    if (playingRef.current) void standby.play().catch(() => undefined);
43|    if (!faded && playingRef.current) {
44|      standby.volume = 0;
45|      const step = volume / 15;
46|      const timer = window.setInterval(() => {
47|        standby.volume = Math.min(volume, standby.volume + step);
48|        live.volume = Math.max(0, live.volume - step);
49|        if (standby.volume >= volume) {
50|          window.clearInterval(timer);
51|          live.pause();
52|          liveRef.current = 1 - liveRef.current;
53|        }
54|      }, 100);
55|      return () => window.clearInterval(timer);
56|    }
57|    live.pause();
58|    liveRef.current = 1 - liveRef.current;
59|  }, [track, started, volume, faded]);
60|
61|  function toggle() {
62|    const live = [firstRef.current, secondRef.current][liveRef.current];
63|    if (!live) return;
64|    if (!started) {
65|      setStarted(true);
66|      if (track) {
67|        live.src = track.src;
68|        void live.play().catch(() => undefined);
69|      }
70|      setPlaying(true);
71|      return;
72|    }
73|    if (live.paused) {
74|      void live.play().catch(() => undefined);
75|      setPlaying(true);
76|    } else {
77|      live.pause();
78|      setPlaying(false);
79|    }
80|  }
81|
82|  return (
83|    <div className="player" role="region" aria-label="Music player">
84|      <audio ref={firstRef} loop preload="auto" />
85|      <audio ref={secondRef} loop preload="auto" />
86|      <button type="button" onClick={toggle} aria-label={playing ? "Pause music" : "Play music"}>
87|        {playing ? "Pause" : "Play"}
88|      </button>
89|      <span className="player-track" aria-live="polite">
90|        {track ? track.label : "Music unavailable"}
91|        {sceneTitle ? ` · ${sceneTitle}` : ""}
92|      </span>
93|      <label className="player-volume">
94|        Volume
95|        <input
96|          type="range"
97|          min={0}
98|          max={1}
99|          step={0.05}
100|          value={volume}
101|          onChange={(e) => setVolume(Number(e.target.value))}
102|          aria-label="Volume"
103|        />
104|      </label>
105|      {onSkip && (
106|        <button type="button" onClick={onSkip} aria-label="Change track">
107|          Change track
108|        </button>
109|      )}
110|    </div>
111|  );
112|}

