1|"use client";
2|
3|import { useCallback, useEffect, useRef, useState } from "react";
4|import { nextAlternative, parseManifest, selectTrack } from "@/core/music";
5|import type { MusicManifest, SceneEmotion, Track } from "@/core/music";
6|import { pickActiveScene } from "./active-scene";
7|import { Player } from "./player";
8|
9|export interface SceneMeta {
10|  id: string;
11|  title: string;
12|  emotion: SceneEmotion | null;
13|}
14|
15|interface ReaderState {
16|  activeId: string | null;
17|  manifest: MusicManifest | null;
18|  currentId: string | null;
19|  override: { sceneId: string; trackId: string } | null;
20|}
21|
22|// Client container: tracks the active scene, fetches the manifest once,
23|// and picks the track. The book text arrives as server-rendered children.
24|export function Reader({ scenes, children }: { scenes: SceneMeta[]; children: React.ReactNode }) {
25|  const [activeId, setActiveId] = useState<string | null>(scenes[0]?.id ?? null);
26|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
27|  const [musicFailed, setMusicFailed] = useState(false);
28|  const [currentId, setCurrentId] = useState<string | null>(null);
29|  const [override, setOverride] = useState<ReaderState["override"]>(null);
30|  const byId = useRef(new Map(scenes.map((s) => [s.id, s])));
31|  byId.current = new Map(scenes.map((s) => [s.id, s]));
32|
33|  // A skip holds until the next scene. On change, selection runs again
34|  // with the override track as current, so hysteresis compares against
35|  // what the user last heard.
36|  const applyScene = useCallback(
37|    (sceneId: string, st: ReaderState) => {
38|      if (st.activeId === sceneId) return null;
39|      const base = st.override && st.override.sceneId !== sceneId ? st.override.trackId : st.currentId;
40|      const emotion = byId.current.get(sceneId)?.emotion ?? null;
41|      const next = st.manifest ? selectTrack(emotion, st.manifest, base) : null;
42|      return {
43|        activeId: sceneId,
44|        currentId: next ? next.id : emotion === null ? base : null,
45|      };
46|    },
47|    [],
48|  );
49|
50|  const stateRef = useRef<ReaderState>({ activeId, manifest, currentId, override });
51|  stateRef.current = { activeId, manifest, currentId, override };
52|  const applyRef = useRef(applyScene);
53|  applyRef.current = applyScene;
54|
55|  function commitScene(sceneId: string) {
56|    const update = applyRef.current(sceneId, stateRef.current);
57|    if (!update) return;
58|    setActiveId(update.activeId);
59|    setCurrentId(update.currentId);
60|    setOverride(null);
61|  }
62|
63|  useEffect(() => {
64|    let cancelled = false;
65|    fetch("/music/manifest.json")
66|      .then((res) => {
67|        if (!res.ok) throw new Error(`manifest ${res.status}`);
68|        return res.json();
69|      })
70|      .then((json: unknown) => {
71|        if (cancelled) return;
72|        setManifest(parseManifest(json));
73|      })
74|      .catch(() => {
75|        if (!cancelled) setMusicFailed(true);
76|      });
77|    return () => {
78|      cancelled = true;
79|    };
80|  }, []);
81|
82|  // Reselect once the manifest lands so the first scene gets music.
83|  useEffect(() => {
84|    if (!manifest) return;
85|    const st = stateRef.current;
86|    if (!st.activeId || st.currentId) return;
87|    const emotion = byId.current.get(st.activeId)?.emotion ?? null;
88|    const next = selectTrack(emotion, manifest, null);
89|    if (next) setCurrentId(next.id);
90|  }, [manifest]);
91|
92|  useEffect(() => {
93|    const readActive = (intersecting: { id: string; top: number; hit: boolean }[]) => {
94|      const lineY = window.innerHeight / 3;
95|      return pickActiveScene(
96|        intersecting.map((e) => ({ id: e.id, top: e.top, intersecting: e.hit })),
97|        lineY,
98|        stateRef.current.activeId,
99|      );
100|    };
101|    const snapshot = (hit: boolean) =>
102|      [...document.querySelectorAll<HTMLElement>("section[data-scene-id]")].map((el) => ({
103|        id: el.dataset.sceneId ?? "",
104|        top: el.getBoundingClientRect().top,
105|        hit,
106|      }));
107|    const observer = new IntersectionObserver(
108|      (entries) => {
109|        const next = readActive(
110|          entries.map((e) => ({
111|            id: (e.target as HTMLElement).dataset.sceneId ?? "",
112|            top: e.boundingClientRect.top,
113|            hit: e.isIntersecting,
114|          })),
115|        );
116|        if (next) commitScene(next);
117|      },
118|      { rootMargin: "-30% 0px -65% 0px" },
119|    );
120|    document.querySelectorAll("section[data-scene-id]").forEach((el) => observer.observe(el));
121|    const first = readActive(snapshot(true));
122|    if (first) commitScene(first);
123|    return () => observer.disconnect();
124|    // eslint-disable-next-line react-hooks/exhaustive-deps
125|  }, []);
126|
127|  function skip() {
128|    const st = stateRef.current;
129|    if (!st.manifest || !st.activeId) return;
130|    const emotion = byId.current.get(st.activeId)?.emotion ?? null;
131|    const next = nextAlternative(emotion, st.manifest, st.currentId);
132|    if (next) {
133|      setCurrentId(next.id);
134|      setOverride({ sceneId: st.activeId, trackId: next.id });
135|    }
136|  }
137|
138|  const track: Track | null = manifest?.tracks.find((t) => t.id === currentId) ?? null;
139|  const sceneTitle = (activeId && byId.current.get(activeId)?.title) || null;
140|  const empty = manifest !== null && manifest.tracks.length === 0;
141|
142|  return (
143|    <>
144|      <div className="player-bar">
145|        {musicFailed || empty ? (
146|          <p className="player-note">Music unavailable. The reader works without it.</p>
147|        ) : (
148|          <Player track={manifest ? track : null} sceneTitle={sceneTitle} onSkip={manifest ? skip : null} />
149|        )}
150|      </div>
151|      {children}
152|    </>
153|  );
154|}

