72|
73|function cosine(a: number[], b: number[]): number {
74|  let dot = 0;
75|  let na = 0;
76|  let nb = 0;
77|  for (let i = 0; i < a.length; i++) {
78|    const x = a[i] ?? 0;
79|    const y = b[i] ?? 0;
80|    dot += x * y;
81|    na += x * x;
82|    nb += y * y;
83|  }
84|  if (na === 0 || nb === 0) return 0;
85|  return dot / (Math.sqrt(na) * Math.sqrt(nb));
86|}
87|
88|function ranked(scene: SceneEmotion | null, manifest: MusicManifest, currentTrackId: string | null): Track[] {
89|  if (scene === null) {
90|    // Failed scene with no vector: hold the current track first for stability.
91|    const current = manifest.tracks.find((t) => t.id === currentTrackId);
92|    const rest = manifest.tracks.filter((t) => t.id !== currentTrackId);
93|    return current ? [current, ...rest] : [...rest];
94|  }
95|  const target = buildFeatures(scene);
96|  return [...manifest.tracks].sort((a, b) => {
97|    const diff = cosine(buildFeatures(b), target) - cosine(buildFeatures(a), target);
98|    return diff !== 0 ? diff : manifest.tracks.indexOf(a) - manifest.tracks.indexOf(b);
99|  });
100|}
101|
102|// Nearest track by cosine similarity over vector plus weighted intensity
103|// and tempo. Hysteresis keeps the current track unless the best beats it
104|// by margin (default 0.05), which stops flicker between nearby scenes.
105|export function selectTrack(
106|  scene: SceneEmotion | null,
107|  manifest: MusicManifest,
108|  currentTrackId?: string | null,
109|  opts?: { margin?: number; exclude?: string[] },
110|): Track | null {
111|  if (manifest.tracks.length === 0) return null;
112|  const current = manifest.tracks.find((t) => t.id === (currentTrackId ?? null)) ?? null;
113|  if (scene === null) return current;
114|  const margin = opts?.margin ?? 0.05;
115|  const excluded = new Set(opts?.exclude ?? []);
116|  const candidates = ranked(scene, manifest, currentTrackId ?? null).filter((t) => !excluded.has(t.id));
117|  const best = candidates[0] ?? null;
118|  if (best === null) return null;
119|  if (current !== null && !excluded.has(current.id) && best.id !== current.id) {
120|    const target = buildFeatures(scene);
121|    if (cosine(buildFeatures(best), target) - cosine(buildFeatures(current), target) < margin) {
122|      return current;
123|    }
124|  }
125|  return best;
126|}
127|
128|// Next best track after the current one, wrapping around, so repeated
129|// presses cycle through every track. One track returns itself.
130|export function nextAlternative(
131|  scene: SceneEmotion | null,
132|  manifest: MusicManifest,
133|  currentTrackId: string | null,
134|): Track | null {
135|  if (manifest.tracks.length === 0) return null;
136|  if (manifest.tracks.length === 1) return manifest.tracks[0] ?? null;
137|  const order = ranked(scene, manifest, currentTrackId);
138|  const at = order.findIndex((t) => t.id === currentTrackId);
139|  return order[(at + 1) % order.length] ?? null;
