1|// Pure part of active scene tracking: from observer entries pick the scene
2|// whose section top sits nearest above the reading line. Keeps the current
3|// scene when nothing qualifies, so fast scrolls never blank the music.
4|export interface SceneEntry {
5|  id: string;
6|  top: number;
7|  intersecting: boolean;
8|}
9|
10|export function pickActiveScene(
11|  entries: SceneEntry[],
12|  lineY: number,
13|  current: string | null,
14|): string | null {
15|  let best: string | null = null;
16|  let bestTop = -Infinity;
17|  for (const entry of entries) {
18|    if (!entry.intersecting) continue;
19|    if (entry.top <= lineY && entry.top > bestTop) {
20|      bestTop = entry.top;
21|      best = entry.id;
22|    }
23|  }
24|  return best ?? current;
25|}

