18|  const secondRef = useRef<HTMLAudioElement | null>(null);
19|  const liveRef = useRef(0);
20|  const [started, setStarted] = useState(false);
21|  const [playing, setPlaying] = useState(false);
22|  const [volume, setVolume] = useState(0.8);
23|  const playingRef = useRef(false);
24|  playingRef.current = playing;
25|
